@tool
extends Node

func rescan() -> String:
	EditorInterface.get_resource_filesystem().scan()
	call_deferred("_import_glb")
	return "IMPORT_SCAN_REQUESTED"

func _import_glb() -> void:
	EditorInterface.get_resource_filesystem().update_file("res://probe_swing.glb")
	EditorInterface.get_resource_filesystem().reimport_files(PackedStringArray(["res://probe_swing.glb"]))

func rig_info() -> Dictionary:
	var rig := get_parent().get_node("World/ImportedProbe")
	var players := rig.find_children("*", "AnimationPlayer", true, false)
	var skeletons := rig.find_children("*", "Skeleton3D", true, false)
	if players.is_empty() or skeletons.is_empty():
		return {"error": "GLB missing player or skeleton"}
	var player: AnimationPlayer = players[0]
	var skeleton: Skeleton3D = skeletons[0]
	return {"animations": player.get_animation_list(), "bones": skeleton.get_bone_count(), "bone_name": skeleton.get_bone_name(0)}

func start_probe() -> Dictionary:
	var rig := get_parent().get_node("World/ImportedProbe")
	var player: AnimationPlayer = rig.find_children("*", "AnimationPlayer", true, false)[0]
	for name in player.get_animation_list():
		if name != "RESET":
			var animation := player.get_animation(name)
			animation.loop_mode = Animation.LOOP_LINEAR
			player.play(name)
			return {"GLB_PLAYING": true, "animation": name, "tracks": animation.get_track_count(), "length": animation.length}
	return {"error": "No imported animation"}

func snapshot() -> Dictionary:
	var rig := get_parent().get_node("World/ImportedProbe")
	var player: AnimationPlayer = rig.find_children("*", "AnimationPlayer", true, false)[0]
	var skeleton: Skeleton3D = rig.find_children("*", "Skeleton3D", true, false)[0]
	return {"playing": player.is_playing(), "position": player.current_animation_position, "rotation": str(skeleton.get_bone_pose_rotation(0))}

func _ready() -> void:
	if not Engine.is_editor_hint():
		print(start_probe())
